    def is_async_gen_callable(self) -> bool:
        return inspect.isasyncgenfunction(inspect.unwrap(self.call))

    @property
    def is_coroutine_callable(self) -> bool:
        return inspect.iscoroutinefunction(inspect.unwrap(self.call))
```

I will now submit the patch.

